/* SOVEREIGN 1.0 — local-first personal command centre. No external APIs or tracking. */
(()=>{'use strict';
const KEY='sovereign.command.v1', MIN=60000, DAY=86400000;
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const pad=n=>String(n).padStart(2,'0');
const dateKey=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const at=(d,h=0,m=0)=>new Date(d+'T'+pad(h)+':'+pad(m)+':00');
const today=()=>dateKey(new Date());
const addDays=(d,n)=>{const x=at(d,12);x.setDate(x.getDate()+n);return dateKey(x)};
const dateNice=(d,opts={weekday:'long',month:'long',day:'numeric'})=>at(d,12).toLocaleDateString('en-GB',opts);
const shortDate=d=>dateNice(d,{month:'short',day:'numeric'});
const timeNice=(t)=>t?String(t).slice(0,5):'All day';
const toMins=t=>{const [h,m]=(t||'00:00').split(':').map(Number);return h*60+m};
const fmtMins=m=>`${Math.floor(m/60)}h ${pad(m%60)}m`;
const cap=s=>s?s[0].toUpperCase()+s.slice(1):'';
const DEMO=()=>{const d=today(),tom=addDays(d,1);return {version:1,profile:{name:'Luka'},sample:true,events:[{id:uid(),date:d,time:'09:00',duration:60,title:'Morning briefing & priorities',category:'personal',place:'',notes:'Sample event — tap to edit.'},{id:uid(),date:d,time:'14:30',duration:75,title:'Deep work session',category:'work',place:'',notes:'Your day, under your command.'},{id:uid(),date:d,time:'18:00',duration:75,title:'Training',category:'health',place:'',notes:''},{id:uid(),date:tom,time:'11:00',duration:45,title:'Planning session',category:'work',place:'',notes:''}],tasks:[{id:uid(),title:'Set three priorities for today',due:d,priority:'high',done:false,missionId:'',notes:''},{id:uid(),title:'Create your first mission',due:d,priority:'normal',done:false,missionId:'',notes:''},{id:uid(),title:'Explore the command centre',due:tom,priority:'low',done:false,missionId:'',notes:''}],missions:[{id:uid(),title:'Your first mission',description:'This is a sample mission. Make it yours.',deadline:addDays(d,14),category:'Personal',archived:false}],people:[{id:uid(),name:'Example contact',role:'Personal network',email:'',phone:'',birthday:'',lastContact:'',followUp:tom,notes:'A sample contact. Replace or delete.'}],focusSessions:[],debriefs:[],focus:{duration:25*60,remaining:25*60,running:false,startedAt:0},settings:{notifications:false,discreet:false}}};
function normalize(raw){const base=DEMO();if(!raw||typeof raw!=='object')return base;const out={...base,...raw,profile:{...base.profile,...(raw.profile||{})},settings:{...base.settings,...(raw.settings||{})},focus:{...base.focus,...(raw.focus||{})}};for(const k of ['events','tasks','missions','people','focusSessions','debriefs'])out[k]=Array.isArray(raw[k])?raw[k].filter(x=>x&&typeof x==='object').slice(0,5000):[];out.sample=Boolean(raw.sample);return out}
let db;try{const raw=localStorage.getItem(KEY);db=raw?normalize(JSON.parse(raw)):DEMO()}catch(e){db=DEMO()}
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){toast('Storage unavailable. Export a backup before closing.')}};
if(!localStorage.getItem(KEY))persist();
let view='briefing',selected=today(),offset=0,missionFilter='active',peopleFilter='all',pendingQ=null,toastTimer=0,installPrompt=null,chartRange=7;
const main=$('#main'),overlay=$('#modal-overlay'),modal=$('#modal');
const chron=(a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||'');
const eventsOn=d=>db.events.filter(e=>e.date===d).sort(chron);
const tasksOpen=()=>db.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')+(({high:-2,normal:0,low:2}[a.priority]||0)-({high:-2,normal:0,low:2}[b.priority]||0)));
const dueTasks=d=>db.tasks.filter(t=>!t.done&&(!t.due||t.due<=d));
const missionTasks=id=>db.tasks.filter(t=>t.missionId===id);
const progress=id=>{const t=missionTasks(id);return t.length?Math.round(t.filter(x=>x.done).length/t.length*100):0};
const nextEvents=(d,n=5)=>db.events.filter(e=>e.date>=d).sort(chron).slice(0,n);
const nDay=(d)=>Math.round((at(d,12)-at(today(),12))/DAY);
const displayName=()=>esc((db.profile.name||'Operator').trim().split(/\s+/)[0]);
const greeting=()=>{const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'};
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3300)}
function sampleBanner(){return db.sample?`<div class="sample-banner">${icon('compass')} <span>EXPLORATION MODE · These are example events and contacts, not your real schedule.</span><button class="text-btn" data-action="clear-sample">Start fresh ${icon('arrow')}</button></div>`:''}
function heading(k,title,subtitle,right=''){return `<div class="headline-row"><div><div class="page-kicker">${k}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${right}</div>`}
function empty(title,descr,action='',label='Add new'){return `<div class="empty"><div class="empty-illustration">${icon('compass')}</div><h3>${title}</h3><p>${descr}</p>${action?`<button class="outline-btn" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`}
function scheduleItem(e){return `<div class="schedule-item" data-action="edit-event" data-id="${esc(e.id)}"><span class="schedule-time">${esc(timeNice(e.time))}</span><span class="schedule-mark ${esc(e.category||'other')}"></span><div class="schedule-desc"><div class="schedule-title private-data">${esc(e.title)}</div><div class="schedule-meta">${esc(e.category||'Event')}${e.duration?' · '+esc(fmtMins(Number(e.duration))):''}${e.place?' · '+esc(e.place):''}</div></div><span class="schedule-icon">${icon('chevron')}</span></div>`}
function taskRow(t){const m=db.missions.find(x=>x.id===t.missionId);return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" class="task-check" data-task="${esc(t.id)}" aria-label="Mark ${esc(t.title)} complete" ${t.done?'checked':''}/><div class="task-body"><div class="task-title private-data">${esc(t.title)}</div><div class="task-meta">${t.priority==='high'?'<span class="badge gold">Priority</span>':''}${m?`<span>${esc(m.title)}</span>`:''}<span>${t.due?esc(shortDate(t.due)):'No due date'}</span></div></div><button class="task-menu" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Edit task">${icon('more')}</button></div>`}
function missionCard(m){const t=missionTasks(m.id),p=progress(m.id),due=m.deadline?nDay(m.deadline):null;return `<article class="surface mission-card" data-action="mission-detail" data-id="${esc(m.id)}" role="button" tabindex="0"><div class="mission-top"><span class="badge gold">${esc(m.category||'Mission')}</span><span class="badge ${m.archived?'dim':due!==null&&due<0?'danger':due!==null&&due<4?'gold':'dim'}">${m.archived?'Archived':due===null?'Ongoing':due<0?'Overdue':due===0?'Due today':due+' days left'}</span></div><h3 class="private-data">${esc(m.title)}</h3><p>${esc(m.description||'No mission brief yet.')}</p><div class="mission-bottom"><div class="progress-track"><span style="width:${p}%"></span></div><div class="progress-text"><span>${t.filter(x=>x.done).length} / ${t.length} actions completed</span><span>${p}%</span></div></div></article>`}
function personCard(p){const fu=p.followUp?nDay(p.followUp):null;return `<article class="surface person-card" data-action="person-detail" data-id="${esc(p.id)}" role="button" tabindex="0"><div class="person-avatar private-data">${esc(p.name.split(' ').slice(0,2).map(x=>x[0]||'').join('').toUpperCase())}</div><div class="person-info"><h3 class="private-data">${esc(p.name)}</h3><p>${esc(p.role||'Personal contact')}</p><span class="badge ${fu!==null&&fu<=0?'gold':'dim'}">${fu===null?'No follow-up':fu<0?'Follow-up overdue':fu===0?'Follow up today':fu===1?'Tomorrow':shortDate(p.followUp)}</span></div><span class="go">${icon('chevron')}</span></article>`}
function renderBriefing(){const d=today(),ev=eventsOn(d),active=dueTasks(d).slice(0,4),up=nextEvents(d,1)[0],completed=db.tasks.filter(t=>t.done&&t.completedAt===d).length,focus=db.focusSessions.filter(x=>x.date===d).reduce((n,x)=>n+x.minutes,0),tot=dueTasks(d).length+completed,readiness=tot?Math.round(completed/tot*100):100;
 main.innerHTML=sampleBanner()+heading('The private command',`${greeting()}, <em>${displayName()}.</em>`,'Every detail in its place. Your day, under your command.',`<button class="outline-btn" data-action="new-event">${icon('plus')} Add appointment</button>`)+`<div class="dash-grid"><div class="stack"><section class="hero surface"><div class="hero-inner"><div class="hero-kicker">${esc(dateNice(d,{weekday:'long',month:'long',day:'numeric'}).toUpperCase())}</div><h2 class="hero-title">The day is <i>yours.</i></h2><p class="hero-description">${ev.length?`You have ${ev.length} appointment${ev.length===1?'':'s'} today.`:'Your schedule is clear.'} ${dueTasks(d).length?`${dueTasks(d).length} action${dueTasks(d).length===1?'':'s'} need your attention.`:'All immediate priorities are accounted for.'}</p><div class="hero-bottom"><button class="gold-btn" data-action="new-task">${icon('plus')} NEW PRIORITY</button><button class="text-btn" data-nav="timeline">VIEW YOUR DAY ${icon('arrow')}</button></div></div><div class="hero-watch"><div class="watch-center">${esc(new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}<span>LOCAL TIME</span></div></div><span class="hero-number">EDITION Nº 001</span></section><div class="metrics"><div class="metric"><div class="metric-label">Appointments</div><div class="metric-value">${ev.length.toString().padStart(2,'0')}</div><div class="metric-sub">Today</div></div><div class="metric"><div class="metric-label">Actions</div><div class="metric-value">${dueTasks(d).length.toString().padStart(2,'0')}</div><div class="metric-sub">Due or unscheduled</div></div><div class="metric"><div class="metric-label">Focus</div><div class="metric-value">${focus}<small> min</small></div><div class="metric-sub">Logged today</div></div></div><section class="surface schedule-card"><div class="section-heading"><h2>YOUR ITINERARY</h2><button class="section-link" data-nav="timeline">FULL TIMELINE ${icon('arrow')}</button></div>${ev.length?`<div class="schedule-list">${ev.slice(0,5).map(scheduleItem).join('')}</div>`:empty('A clear horizon','No appointments scheduled for today.','new-event','Schedule something')}</section><div class="daily-quote"><p>“Discipline is the quiet luxury of a well-lived day.”</p><small>THE SOVEREIGN PRINCIPLE</small></div></div><div class="stack"><section class="surface priority-card"><div class="section-heading"><h2>TOP PRIORITIES</h2><button class="section-link" data-action="new-task">${icon('plus')} ADD</button></div>${active.length?active.map(taskRow).join('')+`<button class="text-btn mt-14" data-nav="missions">ALL ACTIONS ${icon('arrow')}</button>`:empty('Nothing pressing','Add your first priority, or enjoy an open day.','new-task','Create a priority')}</section><section class="surface up-next-card"><div class="page-kicker">NEXT ENGAGEMENT</div>${up?`<h3 class="private-data">${esc(up.title)}</h3><p>${esc(dateNice(up.date))} · ${esc(timeNice(up.time))}${up.place?' · '+esc(up.place):''}</p><button class="outline-btn" data-action="edit-event" data-id="${esc(up.id)}">${icon('arrow')} DETAILS</button>`:`<h3>The calendar is yours.</h3><p>Nothing on the horizon yet.</p><button class="outline-btn" data-action="new-event">${icon('plus')} ADD ENGAGEMENT</button>`}</section><section class="surface debrief-card"><div class="section-heading"><h2>EVENING DEBRIEF</h2><span class="badge green">DAILY RITUAL</span></div><p class="page-subtitle">Capture the day in 30 seconds. Wins, lessons and what comes next.</p><div class="metrics-mini"><div><strong>${completed}</strong><span>Actions done</span></div><div><strong>${readiness}%</strong><span>Progress today</span></div></div><button class="gold-btn mt-20" data-action="debrief">${icon('edit')} WRITE DEBRIEF</button></section><section class="surface up-next-card"><div class="page-kicker">YOUR ASSISTANT</div><h3>Consult Q.</h3><p>Ask about your day, find available time or create a new action — all processed on this device.</p><button class="outline-btn" data-action="q">${icon('spark')} OPEN Q</button></section></div></div>`;}
function dayRail(){let start=addDays(today(),offset);return `<div class="rail-arrows"><button class="icon-btn" data-action="rail-prev" aria-label="Previous seven days">←</button><span>${esc(dateNice(start,{month:'long',year:'numeric'}))}</span><button class="icon-btn" data-action="rail-next" aria-label="Next seven days">→</button><button class="text-btn" data-action="rail-today">TODAY</button></div><div class="date-rail">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);return `<button class="date-cell ${selected===d?'active':''} ${eventsOn(d).length?'has-events':''}" data-date="${d}"><small>${esc(dateNice(d,{weekday:'short'}).toUpperCase())}</small><strong>${at(d,12).getDate()}</strong><span class="date-dot"></span></button>`}).join('')}</div>`}
function timelineBody(){const es=eventsOn(selected);if(!es.length)return empty('A day of possibility','There are no appointments on this date. Add one to shape your day.','new-event','Add appointment');let prev=7*60;let html='';for(const e of es){const s=toMins(e.time);if(s-prev>=45)html+=`<div class="time-gap"><span>${pad(Math.floor(prev/60))}:${pad(prev%60)}</span><span class="time-line dashed"></span><em>${fmtMins(s-prev)} open</em></div>`;html+=`<div class="time-item"><div class="time-point">${esc(timeNice(e.time))}</div><div class="time-line"><b></b></div><div class="time-event ${esc(e.category||'other')}" data-action="edit-event" data-id="${esc(e.id)}"><div class="space-between"><span class="badge gold">${esc(e.category||'Event')}</span><span class="muted">${esc(fmtMins(Number(e.duration)||60))}</span></div><h3 class="private-data">${esc(e.title)}</h3><p>${esc(e.place||'Location not set')}${e.notes?' · '+esc(e.notes.slice(0,80)):''}</p></div></div>`;prev=Math.max(prev,s+(Number(e.duration)||60))}if(prev<22*60)html+=`<div class="time-gap"><span>${pad(Math.floor(prev/60))}:${pad(prev%60)}</span><span class="time-line dashed"></span><em>Open until 22:00 · ${fmtMins(22*60-prev)}</em></div>`;return html}
function renderTimeline(){main.innerHTML=sampleBanner()+heading('Your day, reimagined','The <em>timeline.</em>','Not a calendar grid. A clear view of what matters, when it matters.',`<div class="row wrap"><button class="outline-btn" data-action="import-ics">${icon('upload')} IMPORT .ICS</button><button class="gold-btn" data-action="new-event">${icon('plus')} APPOINTMENT</button></div>`)+dayRail()+`<div class="focus-layout"><section class="surface timeline-panel"><div class="section-heading"><h2>${esc(dateNice(selected).toUpperCase())}</h2><span class="section-note">${eventsOn(selected).length} appointments</span></div><div class="timeline-track">${timelineBody()}</div></section><div class="stack"><section class="surface priority-card"><div class="section-heading"><h2>ACTIONS FOR THIS DATE</h2><button class="section-link" data-action="new-task">${icon('plus')} ADD</button></div>${db.tasks.filter(t=>t.due===selected).length?db.tasks.filter(t=>t.due===selected).map(taskRow).join(''):empty('No actions due','Keep this day open or add a priority.','new-task','Create action')}</section><section class="surface up-next-card"><div class="page-kicker">YOUR OPEN TIME</div><h3>Find some space.</h3><p>Q can show gaps between appointments, from 07:00 to 22:00.</p><button class="outline-btn" data-action="q" data-q="free ${selected}">${icon('spark')} FIND TIME</button></section></div></div>`}
function renderMissions(){let ms=db.missions.filter(m=>missionFilter==='all'||(missionFilter==='active'?!m.archived:m.archived));main.innerHTML=sampleBanner()+heading('The long game','Your <em>missions.</em>','Objectives worth pursuing. Every ambition begins with the next action.',`<button class="gold-btn" data-action="new-mission">${icon('plus')} NEW MISSION</button>`)+`<div class="filter-row"><button class="filter-pill ${missionFilter==='active'?'selected':''}" data-filter="active">Active</button><button class="filter-pill ${missionFilter==='archived'?'selected':''}" data-filter="archived">Archived</button><button class="filter-pill ${missionFilter==='all'?'selected':''}" data-filter="all">All missions</button></div><div class="mission-grid">${ms.length?ms.map(missionCard).join(''):empty('The board is clear','Define your next objective and break it down into manageable actions.','new-mission','Create mission')}</div><div class="section-heading mt-26"><h2>ACTION REGISTER</h2><button class="section-link" data-action="new-task">${icon('plus')} NEW ACTION</button></div><section class="surface priority-card">${db.tasks.length?db.tasks.slice().sort((a,b)=>(Number(a.done)-Number(b.done))||((a.due||'9999').localeCompare(b.due||'9999'))).map(taskRow).join(''):empty('No actions yet','Create a task and connect it to a mission.','new-task','Add an action')}</section>`}
function renderPeople(){let pp=db.people.filter(p=>peopleFilter==='all'||(peopleFilter==='due'&&p.followUp&&p.followUp<=today())||(peopleFilter==='upcoming'&&p.followUp&&p.followUp>today()));pp.sort((a,b)=>(a.followUp||'9999').localeCompare(b.followUp||'9999'));main.innerHTML=sampleBanner()+heading('A gentleman remembers','Your <em>people.</em>','Remember the details that make relationships meaningful.',`<button class="gold-btn" data-action="new-person">${icon('plus')} NEW CONTACT</button>`)+`<div class="filter-row"><button class="filter-pill ${peopleFilter==='all'?'selected':''}" data-person-filter="all">All contacts</button><button class="filter-pill ${peopleFilter==='due'?'selected':''}" data-person-filter="due">Due for follow-up</button><button class="filter-pill ${peopleFilter==='upcoming'?'selected':''}" data-person-filter="upcoming">Upcoming</button></div><div class="person-grid">${pp.length?pp.map(personCard).join(''):empty('Your inner circle awaits','Keep track of important dates, promises and follow-ups.','new-person','Add a contact')}</div><section class="surface up-next-card mt-26"><div class="page-kicker">RELATIONSHIPS ARE BUILT</div><h3>Remember the little things.</h3><p>Birthdays, last conversations and the promises you make. These details stay in your browser, not on our servers.</p></section>`}
function tallyDays(d){const o=[];for(let i=d-1;i>=0;i--){const k=addDays(today(),-i);o.push({date:k,done:db.tasks.filter(t=>t.completedAt===k).length,focus:db.focusSessions.filter(s=>s.date===k).reduce((a,b)=>a+b.minutes,0)})}return o}
function renderIntelligence(){const stats=tallyDays(chartRange),totalFocus=stats.reduce((n,d)=>n+d.focus,0),totalDone=stats.reduce((n,d)=>n+d.done,0),upcoming=db.missions.filter(x=>!x.archived&&x.deadline>=today()).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,3),last=db.debriefs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);main.innerHTML=heading('Your operating picture','Personal <em>intelligence.</em>','A transparent record of your own activity — no mystery scores, no tracking.',`<button class="outline-btn" data-action="export-json">${icon('download')} EXPORT DATA</button>`)+`<div class="analysis-cards"><div class="surface analysis-card"><span class="metric-label">ACTIONS COMPLETED</span><div class="analysis-value">${totalDone}</div><span class="muted">Last ${chartRange} days</span></div><div class="surface analysis-card"><span class="metric-label">FOCUS LOGGED</span><div class="analysis-value">${Math.round(totalFocus/60*10)/10}<small style="font:14px var(--sans)"> h</small></div><span class="muted">Last ${chartRange} days</span></div><div class="surface analysis-card"><span class="metric-label">ACTIVE MISSIONS</span><div class="analysis-value">${db.missions.filter(x=>!x.archived).length}</div><span class="muted">Current objectives</span></div></div><div class="focus-layout"><div class="stack"><section class="surface analysis-card"><div class="section-heading"><h2>FOCUS LOG</h2><div class="row"><button class="filter-pill ${chartRange===7?'selected':''}" data-range="7">7D</button><button class="filter-pill ${chartRange===14?'selected':''}" data-range="14">14D</button></div></div><div class="stat-chart">${stats.map(s=>`<div class="stat-col" title="${esc(shortDate(s.date))}: ${s.focus} minutes"><div class="stat-bar" style="height:${s.focus?Math.max(5,Math.round(s.focus/Math.max(30,...stats.map(x=>x.focus))*100)):2}%"></div><span>${esc(dateNice(s.date,{weekday:'narrow'}))}</span></div>`).join('')}</div><p class="mini-hint mt-14">Minutes completed each day. Only finished sessions are counted.</p></section><section class="surface analysis-card"><div class="section-heading"><h2>COMPLETED ACTIONS</h2></div><div class="stat-chart">${stats.map(s=>`<div class="stat-col" title="${esc(shortDate(s.date))}: ${s.done} completed"><div class="stat-bar" style="height:${s.done?Math.max(8,Math.round(s.done/Math.max(2,...stats.map(x=>x.done))*100)):2}%"></div><span>${esc(dateNice(s.date,{weekday:'narrow'}))}</span></div>`).join('')}</div></section></div><div class="stack"><section class="surface analysis-card"><div class="section-heading"><h2>UPCOMING DEADLINES</h2></div>${upcoming.length?upcoming.map(m=>`<div class="log-entry"><strong class="private-data">${esc(m.title)}</strong><span>${esc(shortDate(m.deadline))}</span></div>`).join(''):'<p class="muted">No deadlines on the horizon.</p>'}</section><section class="surface analysis-card"><div class="section-heading"><h2>RECENT DEBRIEFS</h2><button class="section-link" data-action="debrief">${icon('plus')} ADD</button></div>${last.length?last.map(x=>`<div class="log-entry"><div><strong>${esc(shortDate(x.date))} · ${esc(x.mood)}</strong><div class="muted mt-8 private-data">${esc(x.win||'No note').slice(0,100)}</div></div></div>`).join(''):'<p class="muted">Write your first evening debrief.</p>'}</section></div></div>`}
const remaining=()=>db.focus.running?Math.max(0,db.focus.remaining-Math.floor((Date.now()-db.focus.startedAt)/1000)):db.focus.remaining;
function clockString(n){n=Math.max(0,n);return `${pad(Math.floor(n/60))}:${pad(n%60)}`}
function renderFocus(){const f=db.focus;main.innerHTML=heading('Silence is a strategy','Focus <em>protocol.</em>','One objective. Zero distractions. Your attention is the asset.',`<button class="outline-btn" data-action="new-task">${icon('plus')} NEW ACTION</button>`)+`<div class="focus-layout"><section class="surface focus-main"><div class="page-kicker">DEEP WORK · THE QUIET HOURS</div><div class="focus-dial" id="focus-dial" style="--progress:${(1-remaining()/f.duration)*360}deg"><div class="focus-dial-inner"><div><div class="focus-clock" id="focus-clock">${clockString(remaining())}</div><div class="focus-sub" style="text-align:center">${f.running?'FOCUS IN PROGRESS':'YOUR NEXT SESSION'}</div></div></div></div><div class="focus-controls"><button class="gold-btn" data-action="focus-toggle" id="focus-toggle">${icon(f.running?'pause':'play')} ${f.running?'PAUSE SESSION':'BEGIN SESSION'}</button><button class="outline-btn" data-action="focus-reset">${icon('reset')} RESET</button></div><div class="duration-pills">${[15,25,45,60].map(n=>`<button class="duration-pill ${f.duration===n*60?'selected':''}" data-duration="${n}" ${f.running?'disabled':''}>${n} MIN</button>`).join('')}</div><p class="mini-hint mt-26">The timer continues when you switch tabs. Leave this page open for an end-of-session alert.</p></section><div class="stack"><section class="surface up-next-card"><div class="page-kicker">PREPARE TO EXECUTE</div><h3>Choose your target.</h3><p>Use a focus session for your next mission or clear one priority from today's list.</p>${tasksOpen().slice(0,3).map(t=>`<div class="log-entry"><strong class="private-data">${esc(t.title)}</strong></div>`).join('')||'<p class="muted">No open actions yet.</p>'}</section><section class="surface analysis-card"><div class="section-heading"><h2>RECENT SESSIONS</h2></div>${db.focusSessions.length?db.focusSessions.slice().reverse().slice(0,5).map(s=>`<div class="log-entry"><strong>${s.minutes} minutes</strong><span>${esc(shortDate(s.date))}</span></div>`).join(''):'<p class="muted">Your completed sessions will appear here.</p>'}<button class="text-btn mt-14" data-action="focus-notifications">${icon('mail')} ENABLE SESSION ALERTS</button></section></div></div>`;}
function renderSettings(){main.innerHTML=heading('A discreet operation','Your <em>settings.</em>','Personalize your command centre and keep your information in your own hands.')+`<section class="settings-section"><div class="section-heading"><h2>PERSONALIZATION</h2></div><div class="surface settings-card"><form id="profile-form" class="form-grid"><div class="field full"><label for="profile-name">Your name</label><input id="profile-name" name="name" maxlength="60" required value="${esc(db.profile.name)}"/></div><div class="field full"><button type="submit" class="gold-btn" style="width:max-content">SAVE CHANGES</button></div></form><div class="setting-row"><div><h3>Discreet mode</h3><p>Visually blur event titles, mission names and contacts on screen. This is not encryption.</p></div><button class="outline-btn" data-action="discreet">${db.settings.discreet?'DISABLE':'ENABLE'}</button></div></div></section><section class="settings-section"><div class="section-heading"><h2>YOUR DATA</h2></div><div class="surface settings-card"><div class="setting-row"><div><h3>Export a full backup</h3><p>Download all missions, events, contacts and debriefs as a JSON file.</p></div><button class="outline-btn" data-action="export-json">${icon('download')} JSON</button></div><div class="setting-row"><div><h3>Restore a backup</h3><p>Import a previously exported SOVEREIGN JSON file. This replaces local data.</p></div><button class="outline-btn" data-action="import-json">${icon('upload')} RESTORE</button></div><div class="setting-row"><div><h3>Calendar interoperability</h3><p>Import .ics files (including exports from Google Calendar), or export SOVEREIGN appointments to .ics. Live Google synchronization isn't available.</p></div><div class="row wrap"><button class="outline-btn" data-action="import-ics">IMPORT .ICS</button><button class="outline-btn" data-action="export-ics">EXPORT .ICS</button></div></div><div class="setting-row"><div><h3>Sample records</h3><p>${db.sample?'You are viewing demonstration data. Start fresh when ready.':'Your data is yours.'}</p></div><button class="outline-btn" data-action="clear-sample" ${db.sample?'':'disabled'}>START FRESH</button></div><div class="setting-row"><div><h3>Delete local data</h3><p>Remove everything saved by SOVEREIGN in this browser. This cannot be undone.</p></div><button class="outline-btn danger-text" data-action="erase-all">ERASE DATA</button></div></div></section><section class="surface settings-card"><div class="section-heading"><h2>INSTALL & PRIVACY</h2></div><div class="setting-row"><div><h3>Add to your home screen</h3><p>On iPhone: Safari → Share → Add to Home Screen. On Android, choose Install if your browser offers it.</p></div><button class="outline-btn" data-action="install">${icon('download')} INSTALL</button></div><div class="setting-row"><div><h3>Local-first by design</h3><p>Records are saved in this browser's local storage and can be read by anyone with access to this browser profile. Clear browser data and they may be lost. Export regular backups. The app makes no account, cloud backup or encryption claims.</p></div><span class="badge green">NO ACCOUNT</span></div><div class="setting-row"><div><h3>Q's abilities</h3><p>Q handles a defined set of local commands and calendar calculations. It is not connected to a generative AI model or your Gmail.</p></div><span class="badge dim">ON-DEVICE</span></div></div>`}
function applyPrivacy(){document.body.classList.toggle('discreet',Boolean(db.settings.discreet));$('#discreet-toggle').innerHTML=icon(db.settings.discreet?'eye-off':'eye');$('#discreet-toggle').title=db.settings.discreet?'Reveal sensitive labels':'Mask sensitive labels'}
function render(){const map={briefing:renderBriefing,timeline:renderTimeline,missions:renderMissions,people:renderPeople,intelligence:renderIntelligence,focus:renderFocus,settings:renderSettings};(map[view]||renderBriefing)();$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view));$('#topbar-section').textContent=({briefing:'DAILY BRIEFING',timeline:'YOUR ITINERARY',missions:'MISSION CONTROL',people:'YOUR NETWORK',intelligence:'INTELLIGENCE',focus:'FOCUS PROTOCOL',settings:'SETTINGS & PRIVACY'}[view]||'BRIEFING');$('#topbar-date').textContent=dateNice(today()).toUpperCase();$('#operator-name').textContent=db.profile.name||'Operator';applyPrivacy()}
function navigate(s){view=s;if(s==='timeline'&&selected<today()){selected=today();offset=0}window.scrollTo({top:0,behavior:'smooth'});render()}
const field=(name,label,value='',type='text',opts='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${opts}/></div>`;
const select=(name,label,choices,value)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${choices.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const textarea=(name,label,value='')=>`<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="1600">${esc(value)}</textarea></div>`;
function openModal(title,kicker,body,footer='',large=false){modal.className='modal'+(large?' large':'');modal.innerHTML=`<div class="modal-head"><div><div class="page-kicker">${esc(kicker)}</div><h2>${esc(title)}</h2></div><button class="modal-close" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${body}${footer}`;overlay.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modal input,#modal textarea,#modal button')?.focus(),50)}
function closeModal(){overlay.hidden=true;modal.innerHTML='';document.body.style.overflow='';pendingQ=null}
function modalFoot(save='SAVE CHANGES',deleteBtn=''){return `<div class="modal-foot">${deleteBtn}<button class="outline-btn" type="button" data-action="close-modal">CANCEL</button><button class="gold-btn" type="submit">${save}</button></div>`}
function formModal(title,kicker,formId,fields,isEdit=false,deleteAction='',id=''){openModal(title,kicker,`<form id="${formId}" data-id="${esc(id)}"><div class="modal-body"><div class="form-grid">${fields}</div></div>${modalFoot(isEdit?'SAVE CHANGES':'CREATE',deleteAction?`<button type="button" class="outline-btn danger-text right" data-action="${deleteAction}" data-id="${esc(id)}">${icon('trash')} DELETE</button>`:'')}</form>`)}
function eventForm(id=''){const e=db.events.find(x=>x.id===id)||{title:'',date:selected,time:'09:00',duration:60,category:'work',place:'',notes:''};formModal(id?'Edit engagement':'New engagement','THE ITINERARY','event-form',field('title','Event title',e.title,'text','required maxlength="120" autofocus')+field('date','Date',e.date,'date','required')+field('time','Start time',e.time,'time','required')+select('duration','Duration',[[30,'30 min'],[45,'45 min'],[60,'1 hour'],[75,'1h 15m'],[90,'1h 30m'],[120,'2 hours'],[180,'3 hours'],[240,'4 hours']].map(([a,b])=>[String(a),b]),String(e.duration||60))+select('category','Category',[['work','Work'],['personal','Personal'],['health','Health & training'],['social','Social'],['other','Other']],e.category||'work')+field('place','Location',e.place,'text','maxlength="120"')+textarea('notes','Notes',e.notes),Boolean(id),'delete-event',id)}
function taskForm(id='',missionId=''){const t=db.tasks.find(x=>x.id===id)||{title:'',due:selected,priority:'normal',missionId,notes:''};formModal(id?'Edit action':'New action','ACTION REGISTER','task-form',field('title','Action',t.title,'text','required maxlength="140" autofocus')+field('due','Due date',t.due||'','date')+select('priority','Priority',[['high','High'],['normal','Normal'],['low','Low']],t.priority||'normal')+select('missionId','Mission',[['','Independent action'],...db.missions.filter(m=>!m.archived).map(m=>[m.id,m.title])],t.missionId||'')+textarea('notes','Notes',t.notes),Boolean(id),'delete-task',id)}
function missionForm(id=''){const m=db.missions.find(x=>x.id===id)||{title:'',description:'',deadline:addDays(today(),14),category:'Personal',archived:false};formModal(id?'Edit mission':'New mission','MISSION CONTROL','mission-form',field('title','Mission name',m.title,'text','required maxlength="100" autofocus')+field('deadline','Target date',m.deadline||'','date')+select('category','Category',[['Personal','Personal'],['Work','Work'],['Study','Study'],['Health','Health'],['Travel','Travel'],['Other','Other']],m.category||'Personal')+textarea('description','Mission brief',m.description)+(id?select('archived','Status',[['no','Active'],['yes','Archived']],m.archived?'yes':'no'):'') ,Boolean(id),'delete-mission',id)}
function personForm(id=''){const p=db.people.find(x=>x.id===id)||{name:'',role:'',email:'',phone:'',birthday:'',lastContact:'',followUp:'',notes:''};formModal(id?'Edit contact':'Add contact','PRIVATE ROLODEX','person-form',field('name','Full name',p.name,'text','required maxlength="100" autofocus')+field('role','Role / relationship',p.role,'text','maxlength="100"')+field('email','Email',p.email,'email','maxlength="160"')+field('phone','Phone',p.phone,'tel','maxlength="60"')+field('birthday','Birthday',p.birthday,'date')+field('lastContact','Last contact',p.lastContact,'date')+field('followUp','Next follow-up',p.followUp,'date')+textarea('notes','Personal notes',p.notes),Boolean(id),'delete-person',id)}
function missionDetail(id){const m=db.missions.find(x=>x.id===id);if(!m)return;const tasks=missionTasks(id),p=progress(id);openModal(m.title,'MISSION DOSSIER',`<div class="modal-body"><div class="space-between"><span class="badge gold">${esc(m.category)}</span><span class="badge ${m.archived?'dim':'green'}">${m.archived?'ARCHIVED':'ACTIVE'}</span></div><p class="modal-intro mt-20 private-data">${esc(m.description||'No mission brief yet.')}</p><div class="space-between"><span class="metric-label">${m.deadline?'TARGET · '+esc(shortDate(m.deadline)):'NO DEADLINE'}</span><strong>${p}%</strong></div><div class="progress-track mt-14"><span style="width:${p}%"></span></div><div class="section-heading mt-26"><h2>ACTIONS</h2><button class="section-link" data-action="new-task" data-mission="${esc(id)}">${icon('plus')} ADD</button></div>${tasks.length?tasks.map(taskRow).join(''):'<p class="muted">No actions linked to this mission yet.</p>'}</div><div class="modal-foot"><button class="outline-btn" data-action="edit-mission" data-id="${esc(id)}">${icon('edit')} EDIT MISSION</button><button class="gold-btn" data-action="new-task" data-mission="${esc(id)}">${icon('plus')} ADD ACTION</button></div>`,true)}
function personDetail(id){const p=db.people.find(x=>x.id===id);if(!p)return;openModal(p.name,'CONTACT DOSSIER',`<div class="modal-body"><div class="row"><div class="person-avatar private-data">${esc(p.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</div><div><strong>${esc(p.role||'Personal contact')}</strong><p class="muted mt-8">${p.lastContact?'Last contact: '+esc(shortDate(p.lastContact)):'No last-contact date'}</p></div></div><div class="subtle-rule"></div>${p.email?`<p><span class="metric-label">EMAIL</span><br><a href="mailto:${encodeURIComponent(p.email)}" class="private-data">${esc(p.email)}</a></p>`:''}${p.phone?`<p><span class="metric-label">PHONE</span><br><a href="tel:${esc(p.phone.replace(/[^+0-9]/g,''))}" class="private-data">${esc(p.phone)}</a></p>`:''}${p.birthday?`<p><span class="metric-label">BIRTHDAY</span><br>${esc(shortDate(p.birthday))}</p>`:''}${p.followUp?`<p><span class="metric-label">NEXT FOLLOW-UP</span><br>${esc(dateNice(p.followUp))}</p>`:''}<p class="muted private-data" style="white-space:pre-wrap">${esc(p.notes||'No notes yet.')}</p></div><div class="modal-foot"><button class="outline-btn" data-action="contact-today" data-id="${esc(id)}">${icon('check')} SPOKE TODAY</button><button class="gold-btn" data-action="edit-person" data-id="${esc(id)}">${icon('edit')} EDIT</button></div>`)}
function debriefModal(){const d=today(),existing=db.debriefs.find(x=>x.date===d)||{mood:'Good',win:'',lesson:'',tomorrow:''};openModal('Evening debrief','THE DAILY RECORD',`<form id="debrief-form"><div class="modal-body"><p class="modal-intro">A short reflection closes the loop. Only you can decide how the day went.</p><div class="field"><label>How was today?</label><div class="mood-group">${['Excellent','Good','Mixed','Difficult'].map(m=>`<button type="button" class="mood-btn ${existing.mood===m?'active':''}" data-mood="${m}">${m}</button>`).join('')}</div><input type="hidden" name="mood" id="mood-value" value="${esc(existing.mood)}"/></div><div class="form-grid mt-26">${textarea('win','One thing that went well',existing.win)}${textarea('lesson','What did you learn?',existing.lesson)}${textarea('tomorrow','Tomorrow’s most important action',existing.tomorrow)}</div></div>${modalFoot('SAVE DEBRIEF')}</form>`)}
function saveForm(form){const fd=new FormData(form),str=k=>String(fd.get(k)||'').trim(),id=form.dataset.id||uid();if(form.id==='profile-form'){db.profile.name=str('name').slice(0,60)||'Operator';persist();toast('Profile updated.');render();return}if(form.id==='event-form'){const v={id,title:str('title').slice(0,120),date:str('date'),time:str('time'),duration:Number(str('duration'))||60,category:str('category'),place:str('place').slice(0,120),notes:str('notes').slice(0,1600)};if(!v.title||!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||!/^\d\d:\d\d$/.test(v.time))return toast('Enter a title, date and time.');upsert('events',v);selected=v.date;toast('Engagement saved.')}if(form.id==='task-form'){const old=db.tasks.find(x=>x.id===id)||{};const v={...old,id,title:str('title').slice(0,140),due:str('due'),priority:str('priority'),missionId:str('missionId'),notes:str('notes').slice(0,1600),done:old.done||false};if(!v.title)return toast('Please name the action.');upsert('tasks',v);toast('Action saved.')}if(form.id==='mission-form'){const v={id,title:str('title').slice(0,100),description:str('description').slice(0,1600),deadline:str('deadline'),category:str('category'),archived:str('archived')==='yes'};if(!v.title)return toast('Please name the mission.');upsert('missions',v);toast('Mission saved.')}if(form.id==='person-form'){const v={id,name:str('name').slice(0,100),role:str('role').slice(0,100),email:str('email').slice(0,160),phone:str('phone').slice(0,60),birthday:str('birthday'),lastContact:str('lastContact'),followUp:str('followUp'),notes:str('notes').slice(0,1600)};if(!v.name)return toast('Please enter a contact name.');upsert('people',v);toast('Contact saved.')}if(form.id==='debrief-form'){const v={date:today(),mood:str('mood'),win:str('win').slice(0,1600),lesson:str('lesson').slice(0,1600),tomorrow:str('tomorrow').slice(0,1600)};db.debriefs=db.debriefs.filter(x=>x.date!==v.date);db.debriefs.push(v);toast('Debrief recorded.')}persist();closeModal();render()}
function upsert(key,v){const i=db[key].findIndex(x=>x.id===v.id);if(i<0)db[key].push(v);else db[key][i]=v}
function remove(key,id){const item=db[key].find(x=>x.id===id);if(!item)return;const label={events:'engagement',tasks:'action',missions:'mission',people:'contact'}[key];if(!window.confirm(`Delete this ${label}? This cannot be undone.`))return;if(key==='missions')db.tasks.forEach(t=>{if(t.missionId===id)t.missionId=''});db[key]=db[key].filter(x=>x.id!==id);persist();closeModal();render();toast(cap(label)+' deleted.');}
function toggleTask(id,checked){const t=db.tasks.find(x=>x.id===id);if(!t)return;t.done=checked;t.completedAt=checked?today():null;persist();render();if(!overlay.hidden&&modal.querySelector('[data-action="mission-detail"]'))missionDetail(t.missionId)}
function markContact(id){const p=db.people.find(x=>x.id===id);if(p){p.lastContact=today();p.followUp='';persist();closeModal();render();toast('Contact record updated.')}}
function focusToggle(){if(db.focus.running){db.focus.remaining=remaining();db.focus.running=false;db.focus.startedAt=0}else{if(remaining()<=0)db.focus.remaining=db.focus.duration;db.focus.running=true;db.focus.startedAt=Date.now()}persist();render()}
function focusFinish(){if(!db.focus.running)return;db.focus.running=false;db.focus.remaining=0;db.focus.startedAt=0;db.focusSessions.push({id:uid(),date:today(),minutes:Math.round(db.focus.duration/60)});persist();if('Notification'in window&&Notification.permission==='granted')new Notification('Focus protocol complete',{body:'Excellent work. Your session is complete.'});toast('Session completed.');if(view==='focus')render()}
function focusReset(){db.focus.running=false;db.focus.startedAt=0;db.focus.remaining=db.focus.duration;persist();render()}
function ticking(){if(db.focus.running&&remaining()<=0)focusFinish();if(view==='focus'&&!db.focus.running)return;const c=$('#focus-clock'),dial=$('#focus-dial');if(c&&dial){c.textContent=clockString(remaining());dial.style.setProperty('--progress',`${(1-remaining()/db.focus.duration)*360}deg`)}}
function downloadFile(name,type,content){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const icsEsc=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
function icsExport(){const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SOVEREIGN//Private Command//EN','CALSCALE:GREGORIAN',...db.events.map(e=>{const start=at(e.date,...(e.time||'09:00').split(':').map(Number));const end=new Date(start.getTime()+Number(e.duration||60)*MIN);const dt=x=>dateKey(x).replace(/-/g,'')+'T'+pad(x.getHours())+pad(x.getMinutes())+'00';return ['BEGIN:VEVENT','UID:'+e.id+'@sovereign.local','DTSTART:'+dt(start),'DTEND:'+dt(end),'SUMMARY:'+icsEsc(e.title),'LOCATION:'+icsEsc(e.place),'DESCRIPTION:'+icsEsc(e.notes),'END:VEVENT'].join('\r\n')}),'END:VCALENDAR'];downloadFile('sovereign-calendar.ics','text/calendar;charset=utf-8',data.join('\r\n'));toast('Calendar exported.')}
function parseICS(content){const lines=String(content).replace(/\r\n[ \t]/g,'').split(/\r?\n/);let active=false,obj={},events=[];for(const line of lines){if(line==='BEGIN:VEVENT'){active=true;obj={};continue}if(line==='END:VEVENT'){active=false;const val=(obj.DTSTART||'').replace(/[^0-9TZ]/g,'');if(val.length>=8){let start;if(/Z$/.test(val)&&val.length>=16){start=new Date(`${val.slice(0,4)}-${val.slice(4,6)}-${val.slice(6,8)}T${val.slice(9,11)}:${val.slice(11,13)}:${val.slice(13,15)}Z`)}else{start=at(`${val.slice(0,4)}-${val.slice(4,6)}-${val.slice(6,8)}`,Number(val.slice(9,11))||0,Number(val.slice(11,13))||0)}let dur=60;if(obj.DTEND){const ed=obj.DTEND.replace(/[^0-9TZ]/g,'');let end;if(/Z$/.test(ed)&&ed.length>=16)end=new Date(`${ed.slice(0,4)}-${ed.slice(4,6)}-${ed.slice(6,8)}T${ed.slice(9,11)}:${ed.slice(11,13)}:${ed.slice(13,15)}Z`);else end=at(`${ed.slice(0,4)}-${ed.slice(4,6)}-${ed.slice(6,8)}`,Number(ed.slice(9,11))||0,Number(ed.slice(11,13))||0);dur=Math.max(15,Math.min(1440,Math.round((end-start)/MIN)||60))}if(!Number.isNaN(start.getTime()))events.push({id:uid(),date:dateKey(start),time:val.length===8?'09:00':pad(start.getHours())+':'+pad(start.getMinutes()),duration:dur,title:(obj.SUMMARY||'Imported event').slice(0,120),place:(obj.LOCATION||'').slice(0,120),notes:(obj.DESCRIPTION||'').slice(0,1600),category:'other'})}continue}if(!active)continue;const ix=line.indexOf(':');if(ix<0)continue;const key=line.slice(0,ix).split(';')[0].toUpperCase(),v=line.slice(ix+1).replace(/\\n/gi,'\n').replace(/\\([,;\\])/g,'$1');obj[key]=v}return events.slice(0,1000)}
function importICS(f){if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const es=parseICS(reader.result);if(!es.length)return toast('No events found in that .ics file.');if(!confirm(`Import ${es.length} events? Check times after import, especially for unusual time zones or recurring events.`))return;db.events.push(...es);db.sample=false;persist();render();toast(`${es.length} events imported.`)}catch(e){toast('Could not read the calendar file.')}};reader.readAsText(f)}
function importJSON(f){if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const obj=JSON.parse(reader.result);if(!obj||!Array.isArray(obj.events)||!Array.isArray(obj.tasks)||!Array.isArray(obj.missions)||!Array.isArray(obj.people))throw Error('Invalid backup');if(!confirm('This will replace all locally saved SOVEREIGN data. Continue?'))return;db=normalize(obj);db.focus.running=false;persist();closeModal();render();toast('Backup restored.')}catch(e){toast('Invalid backup. No changes were made.')}};reader.readAsText(f)}
function clearSamples(){if(!db.sample)return;if(!confirm('Remove all demonstration data and start with an empty command centre?'))return;db={...DEMO(),sample:false,events:[],tasks:[],missions:[],people:[],focusSessions:[],debriefs:[]};persist();closeModal();render();toast('Your space is ready.')}
function eraseAll(){if(!confirm('Permanently erase ALL local SOVEREIGN data on this device?'))return;const typed=prompt('Type ERASE to confirm:');if(typed!=='ERASE')return;db={...DEMO(),sample:false,events:[],tasks:[],missions:[],people:[],focusSessions:[],debriefs:[]};db.profile.name='Operator';persist();closeModal();navigate('briefing');toast('Local data erased.')}
function dateFromWords(text){if(/\btomorrow\b/i.test(text))return addDays(today(),1);if(/\btoday\b/i.test(text))return today();const iso=text.match(/\b(\d{4}-\d{2}-\d{2})\b/);if(iso)return iso[1];const names=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];const w=names.findIndex(d=>new RegExp('\\b'+d+'\\b','i').test(text));if(w>=0){const now=at(today(),12);let diff=(w-now.getDay()+7)%7;if(/next\s+/i.test(text)&&diff===0)diff=7;return addDays(today(),diff)}return null}
function parsedTime(s){const m=s.match(/\b(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);if(!m)return null;let h=Number(m[1]),mi=Number(m[2]||0),ap=(m[3]||'').toLowerCase();if(h>23||mi>59)return null;if(ap==='pm'&&h<12)h+=12;if(ap==='am'&&h===12)h=0;return pad(h)+':'+pad(mi)}
function gapsFor(d){const es=eventsOn(d),gaps=[];let cursor=7*60;for(const e of es){const start=toMins(e.time);if(start>cursor&&start-cursor>=30)gaps.push([cursor,start]);cursor=Math.max(cursor,start+Number(e.duration||60))}if(cursor<22*60)gaps.push([cursor,22*60]);return gaps}
const hTime=n=>pad(Math.floor(n/60))+':'+pad(n%60);
function qOpen(seed=''){pendingQ=null;openModal('','',`<div class="modal-body"><div class="q-shell"><div class="q-logo">Q</div><div><h2>At your service.</h2><small>LOCAL COMMAND ASSISTANT · PRIVATE ON THIS DEVICE</small></div></div><form id="q-form" class="q-entry"><input class="q-input" id="q-input" aria-label="Your command" placeholder="What does tomorrow look like?" value="${esc(seed)}" autofocus autocomplete="off"/><button type="button" class="icon-btn" data-action="q-mic" title="Voice dictation">${icon('mic')}</button><button type="submit" class="gold-btn">${icon('arrow')}</button></form><div class="q-suggestions">${['My briefing','Tomorrow','Free time today','Add a task','New appointment','Mission status'].map(x=>`<button class="q-chip" data-suggest="${esc(x)}">${esc(x)}</button>`).join('')}</div><div id="q-result" class="q-response" hidden></div><p class="mini-hint mt-20">Try: “remind me to call Alex tomorrow” or “schedule dinner tomorrow at 7 pm”. Q understands a small set of commands, not open-ended AI.</p></div>`, '',true);modal.classList.add('q-dialog');if(seed)qAnswer(seed)}
function qAnswer(raw){const input=String(raw||'').trim(),lower=input.toLowerCase(),el=$('#q-result');if(!el)return;let out='',plan=null;const forDate=dateFromWords(lower)||today();if(!input){el.hidden=true;return}if(/^free\s+\d{4}-\d{2}-\d{2}/.test(lower)||/free\s*(time|slots|hours)?|available|open window/.test(lower)){const gaps=gapsFor(forDate);out=`<h4>AVAILABLE TIME · ${esc(shortDate(forDate))}</h4>${gaps.length?`<p>${gaps.map(g=>`${hTime(g[0])}–${hTime(g[1])} (${fmtMins(g[1]-g[0])})`).join('<br>')}</p>`:'<p>No gaps of at least 30 minutes between 07:00 and 22:00.</p>'}`}
else if(/(tomorrow|today|briefing|my day|my schedule|what.*(day|look|plan))/.test(lower)&&!/^(remind|add|schedule|create|new)/.test(lower)){const es=eventsOn(forDate),ts=dueTasks(forDate);out=`<h4>${esc(dateNice(forDate).toUpperCase())} · PRIVATE BRIEFING</h4><p>${es.length} appointment${es.length===1?'':'s'}, ${ts.length} open action${ts.length===1?'':'s'} due by then.</p>${es.length?`<ul>${es.map(e=>`<li>${esc(e.time)} · ${esc(e.title)}</li>`).join('')}</ul>`:'<p>Your calendar is clear.</p>'}${ts.length?`<p><strong>Priorities:</strong> ${ts.slice(0,3).map(t=>esc(t.title)).join(' · ')}</p>`:''}`}
else if(/mission|objective|progress/.test(lower)&&!/^(add|create|new)/.test(lower)){const active=db.missions.filter(m=>!m.archived);out=`<h4>MISSION STATUS</h4><p>${active.length} active missions.</p>${active.length?`<ul>${active.map(m=>`<li>${esc(m.title)} · ${progress(m.id)}%${m.deadline?' · due '+esc(shortDate(m.deadline)):''}</li>`).join('')}</ul>`:'<p>Ready for your first mission.</p>'}`}
else if(/^(add a task|new task|new action)$/.test(lower)){out=`<h4>ACTION REGISTER</h4><p>I can open the action form for you.</p><button class="gold-btn" id="q-apply">${icon('plus')} CREATE ACTION</button>`;plan={type:'form',target:'task'}}
else if(/^(new appointment|add appointment|new event)$/.test(lower)){out=`<h4>THE ITINERARY</h4><p>I can open the appointment form for you.</p><button class="gold-btn" id="q-apply">${icon('plus')} NEW APPOINTMENT</button>`;plan={type:'form',target:'event'}}
else if(/^(remind me to|add task|task:|remember to)\s+/i.test(input)){let title=input.replace(/^(remind me to|add task|task:|remember to)\s+/i,'').replace(/\s+(today|tomorrow|next\s+\w+|monday|tuesday|wednesday|thursday|friday|saturday|sunday)$/i,'').trim();if(title){out=`<h4>REVIEW ACTION</h4><p><strong>${esc(title)}</strong><br>Due: ${esc(dateNice(forDate))}</p><button class="gold-btn" id="q-apply">${icon('check')} ADD TO ACTIONS</button>`;plan={type:'task',title,due:forDate}}}
else if(/^(schedule|book|add event|meeting with|dinner with|appointment)\s+/i.test(input)){let body=input.replace(/^(schedule|book|add event|meeting with|dinner with|appointment)\s+/i,'').trim();const mt=body.match(/\bat\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);const time=mt?parsedTime(mt[0]):null;let title=body.replace(/\s+(today|tomorrow|next\s+\w+|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/ig,'').replace(/\bat\s+\d{1,2}(?::\d{2})?\s*(am|pm)?\b/ig,'').trim();if(time&&title){out=`<h4>REVIEW APPOINTMENT</h4><p><strong>${esc(cap(title))}</strong><br>${esc(dateNice(forDate))} · ${esc(time)} · 1 hour</p><button class="gold-btn" id="q-apply">${icon('check')} ADD TO CALENDAR</button>`;plan={type:'event',title:cap(title),date:forDate,time}}}
else if(/^(start focus|focus now|begin focus)/i.test(lower)){out=`<h4>FOCUS PROTOCOL</h4><p>Your timer is ready.</p><button class="gold-btn" id="q-apply">${icon('focus')} OPEN FOCUS</button>`;plan={type:'form',target:'focus'}}
if(!out)out=`<h4>COMMAND NOT RECOGNIZED</h4><p>Try one of these: “My briefing”, “Free time tomorrow”, “Mission status”, “Remind me to send the report tomorrow”, or “Schedule lunch tomorrow at 12 pm”. Commands are processed locally, not by a cloud AI.</p>`;pendingQ=plan;el.hidden=false;el.innerHTML=out}
function qApply(){const p=pendingQ;if(!p)return;if(p.type==='form'){closeModal();if(p.target==='task')taskForm();if(p.target==='event')eventForm();if(p.target==='focus')navigate('focus');return}if(p.type==='task'){db.tasks.push({id:uid(),title:p.title,due:p.due,priority:'normal',done:false,missionId:'',notes:''})}if(p.type==='event'){db.events.push({id:uid(),title:p.title,date:p.date,time:p.time,duration:60,category:'personal',place:'',notes:''})}db.sample=false;persist();closeModal();render();toast(p.type==='task'?'Action added.':'Appointment scheduled.')}
function speakQ(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voice recognition is not available in this browser. Use the keyboard instead.');try{const rec=new SR();rec.lang='en-US';rec.interimResults=false;rec.onresult=e=>{$('#q-input').value=e.results[0][0].transcript;qAnswer($('#q-input').value)};rec.onerror=()=>toast('Voice input unavailable. Type your command instead.');rec.start()}catch(e){toast('Voice input unavailable.')}}
function action(a,el){const id=el?.dataset.id||'';switch(a){case'new-event':eventForm();break;case'edit-event':eventForm(id);break;case'new-task':taskForm('',el?.dataset.mission||'');break;case'edit-task':taskForm(id);break;case'new-mission':missionForm();break;case'edit-mission':missionForm(id);break;case'mission-detail':missionDetail(id);break;case'new-person':personForm();break;case'edit-person':personForm(id);break;case'person-detail':personDetail(id);break;case'contact-today':markContact(id);break;case'delete-event':remove('events',id);break;case'delete-task':remove('tasks',id);break;case'delete-mission':remove('missions',id);break;case'delete-person':remove('people',id);break;case'close-modal':closeModal();break;case'rail-prev':offset-=7;selected=addDays(today(),offset);render();break;case'rail-next':offset+=7;selected=addDays(today(),offset);render();break;case'rail-today':offset=0;selected=today();render();break;case'debrief':debriefModal();break;case'discreet':db.settings.discreet=!db.settings.discreet;persist();render();toast(db.settings.discreet?'Discreet mode enabled.':'Discreet mode disabled.');break;case'focus-toggle':focusToggle();break;case'focus-reset':focusReset();break;case'focus-notifications':if(!('Notification'in window))return toast('Notifications are not available in this browser.');Notification.requestPermission().then(s=>toast(s==='granted'?'Session alerts enabled.':'Notifications not enabled.'));break;case'export-json':downloadFile('sovereign-backup-'+today()+'.json','application/json',JSON.stringify(db,null,2));toast('Backup exported.');break;case'import-json':$('#import-json').click();break;case'import-ics':$('#import-ics').click();break;case'export-ics':icsExport();break;case'clear-sample':clearSamples();break;case'erase-all':eraseAll();break;case'q':qOpen(el?.dataset.q||'');break;case'q-mic':speakQ();break;case'install':if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>{installPrompt=null})}else toast('On iPhone: Safari → Share → Add to Home Screen.');break;}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}const b=e.target.closest('[data-action]');if(b){action(b.dataset.action,b);return}const d=e.target.closest('[data-date]');if(d){selected=d.dataset.date;render();return}const f=e.target.closest('[data-filter]');if(f){missionFilter=f.dataset.filter;render();return}const pf=e.target.closest('[data-person-filter]');if(pf){peopleFilter=pf.dataset.personFilter;render();return}const range=e.target.closest('[data-range]');if(range){chartRange=Number(range.dataset.range);render();return}const dur=e.target.closest('[data-duration]');if(dur&&!db.focus.running){db.focus.duration=Number(dur.dataset.duration)*60;db.focus.remaining=db.focus.duration;persist();render();return}const mood=e.target.closest('[data-mood]');if(mood){$$('[data-mood]',modal).forEach(x=>x.classList.toggle('active',x===mood));$('#mood-value').value=mood.dataset.mood;return}const suggestion=e.target.closest('[data-suggest]');if(suggestion){$('#q-input').value=suggestion.dataset.suggest;qAnswer($('#q-input').value);return}if(e.target.id==='q-apply'){qApply();return}});
document.addEventListener('submit',e=>{if(e.target.id==='q-form'){e.preventDefault();qAnswer($('#q-input').value);return}if(['event-form','task-form','mission-form','person-form','debrief-form','profile-form'].includes(e.target.id)){e.preventDefault();saveForm(e.target)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-task]')){const id=e.target.dataset.task;const t=db.tasks.find(x=>x.id===id);if(t){t.done=e.target.checked;t.completedAt=t.done?today():null;persist();const md=!overlay.hidden&&modal.querySelector('.modal-head h2')?.textContent;render();if(md){const m=db.missions.find(x=>x.title===md);if(m)missionDetail(m.id)}toast(t.done?'Action completed.':'Action reopened.')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden)closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();qOpen()}if(e.key==='Enter'&&e.target.matches('[role="button"][data-action]')){e.preventDefault();action(e.target.dataset.action,e.target)}});
overlay.addEventListener('mousedown',e=>{if(e.target===overlay)closeModal()});$('#q-fab').addEventListener('click',()=>qOpen());$('#discreet-toggle').addEventListener('click',()=>{db.settings.discreet=!db.settings.discreet;persist();render();toast(db.settings.discreet?'Discreet mode on.':'Discreet mode off.')});$('#import-json').addEventListener('change',e=>{importJSON(e.target.files[0]);e.target.value=''});$('#import-ics').addEventListener('change',e=>{importICS(e.target.files[0]);e.target.value=''});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
setInterval(ticking,1000);if(db.focus.running&&remaining()<=0)focusFinish();render();
})();